import {startPlay,stopPlay,injectPlayPointer,playSnapshot} from '/workspace/scratch/a46295e5abc1/qianxing-simulator-reference/studio/play/session.js';
import {PixiPlayRenderer} from '/workspace/scratch/a46295e5abc1/qianxing-simulator-reference/studio/play/pixi-renderer.js';
const canvas=document.getElementById('stage'),status=document.getElementById('status');let session,renderer,paused=false,last=0,acc=0,paint=0;
const archive=await fetch('./backpack.qx-save.json').then(r=>r.json());
async function start(){if(session)stopPlay(session);session=startPlay(archive.assets.server,{templatesProject:archive.assets.client,scripts:archive.assets.scripts,sceneScripts:archive.assets.scripts,templateScripts:[],canvasId:document.getElementById('device').value});last=0;acc=0;paused=false;document.getElementById('pause').textContent='暂停';if(!renderer)renderer=new PixiPlayRenderer(canvas);const snap=playSnapshot(session,{view:true});await renderer.applyScene(snap.scene,snap.canvasWidth,snap.canvasHeight);status.textContent='正在准备图元池…';}
function point(e){const r=canvas.getBoundingClientRect();return[(e.clientX-r.left)*session.runtime.canvasWidth/r.width,(r.bottom-e.clientY)*session.runtime.canvasHeight/r.height]}
for(const[k,t]of[['pointerdown','down'],['pointerup','up'],['pointermove','move']])canvas.addEventListener(k,e=>{if(!session||paused)return;e.preventDefault();if(t==='down')canvas.setPointerCapture(e.pointerId);injectPlayPointer(session,t,...point(e));});
window.addEventListener('keydown',e=>{const n=e.code.replace('Digit','');if(/^[1-9]$/.test(n)&&session){e.preventDefault();session.runtime.injectKey('KeyboardCraftspersonKey'+n+'Down')}});window.addEventListener('keyup',e=>{const n=e.code.replace('Digit','');if(/^[1-9]$/.test(n)&&session)session.runtime.injectKey('KeyboardCraftspersonKey'+n+'Up')});
document.getElementById('restart').onclick=start;document.getElementById('device').onchange=start;document.getElementById('pause').onclick=()=>{paused=!paused;document.getElementById('pause').textContent=paused?'继续':'暂停';last=0};
let busy=false;async function frame(time){requestAnimationFrame(frame);if(!session||paused||busy)return;busy=true;try{if(!last)last=time;acc=Math.min(.16,acc+(time-last)/1000);last=time;while(acc>=1/30){session.runtime.step(1/30);acc-=1/30}if(time-paint>100){paint=time;const snap=playSnapshot(session,{view:true});await renderer.applyScene(snap.scene,snap.canvasWidth,snap.canvasHeight);const lua=session.runtime.mountedScripts.find(v=>v.path==='backpack/main'),s=lua?.invoke('Inspect',[]);status.textContent=s?.ready?'运行中 · 第'+s.round+'轮 · '+s.wins+'/5胜 · '+s.lives+'生命 · '+s.created+'控件':'正在分批初始化图元…';const errors=session.runtime.logs.filter(v=>/error/i.test(v.level));if(errors.length)throw Error(errors.at(-1).text);}}catch(e){status.textContent='运行错误：'+e.message;console.error(e);paused=true}finally{busy=false}}
await start();requestAnimationFrame(frame);
